//! Checks the parts catalog (`crates/seqcore/data/parts.tsv`), which is generated by
//! `tools/build-catalog.mjs`. The generator checks these too, but it needs the network;
//! this runs offline, so a hand-edited or badly merged catalog can't reach a release.

use seqcore::parts::{catalog_text, parts, Molecule, Part, MIN_BASES, MIN_RESIDUES};
use std::collections::HashMap;

/// GenBank feature types the catalog may use. A type outside this list would be coloured
/// and grouped as a plain misc_feature, so adding one is a deliberate change.
const TYPES: &[&str] = &[
    "CDS",
    "gene",
    "promoter",
    "terminator",
    "rep_origin",
    "protein_bind",
    "misc_feature",
    "misc_recomb",
    "regulatory",
    "RBS",
    "polyA_signal",
    "ncRNA",
    "oriT",
];

/// `defined` means the bases are a record's but the extent is ours, because the record
/// marks the feature as a single base (see docs/feature-catalog.md).
const SOURCES: &[&str] = &["ncbi", "amrfinder", "literal", "defined", "uniprot", "fpbase"];
const LICENCES: &[&str] = &[
    "ncbi-unrestricted",
    "usgov-public-domain",
    "published-sequence",
    "defined-extent",
    "cc-by-4.0",
    "fpbase-open",
];

/// Which licence tag each source must carry, so the two can't drift apart.
const LICENCE_FOR: &[(&str, &str)] = &[
    ("ncbi", "ncbi-unrestricted"),
    ("amrfinder", "usgov-public-domain"),
    ("literal", "published-sequence"),
    ("defined", "defined-extent"),
    ("uniprot", "cc-by-4.0"),
    ("fpbase", "fpbase-open"),
];

fn catalog() -> &'static [Part] {
    parts()
}

#[test]
fn the_catalog_loads() {
    let all = catalog();
    assert!(
        all.len() >= 30,
        "only {} entries; the catalog file may be truncated",
        all.len()
    );
}

#[test]
fn every_entry_is_well_formed() {
    for p in catalog() {
        assert!(!p.id.is_empty(), "an entry has no id");
        assert!(!p.name.is_empty(), "{}: no name", p.id);
        assert_eq!(p.id.trim(), p.id, "{}: id has surrounding space", p.id);
        assert_eq!(p.name.trim(), p.name, "{}: name has surrounding space", p.id);
        assert!(
            TYPES.contains(&p.kind),
            "{}: type {:?} is not one the app groups and colours",
            p.id,
            p.kind
        );
        assert!(SOURCES.contains(&p.source), "{}: unknown source {:?}", p.id, p.source);
        assert!(LICENCES.contains(&p.licence), "{}: unknown licence tag {:?}", p.id, p.licence);
        let expected = LICENCE_FOR.iter().find(|(s, _)| *s == p.source).map(|(_, l)| *l);
        assert_eq!(
            Some(p.licence),
            expected,
            "{}: source {:?} must carry the licence tag {:?}",
            p.id,
            p.source,
            expected.unwrap_or("?")
        );
    }
}

#[test]
fn every_entry_has_a_searchable_sequence() {
    for p in catalog() {
        match p.molecule {
            Molecule::Dna => {
                assert!(
                    p.sequence.bytes().all(|b| matches!(b, b'A' | b'C' | b'G' | b'T')),
                    "{}: bases must be upper-case ACGT only",
                    p.id
                );
                assert!(
                    p.sequence.len() >= MIN_BASES,
                    "{}: {} bases is below the {} floor, so it would match by chance",
                    p.id,
                    p.sequence.len(),
                    MIN_BASES
                );
            }
            Molecule::Protein => {
                assert!(
                    p.sequence.bytes().all(|b| b.is_ascii_uppercase() && !matches!(b, b'B' | b'J' | b'O' | b'U' | b'X' | b'Z')),
                    "{}: residues must be upper-case one-letter amino acids",
                    p.id
                );
                assert!(
                    p.sequence.len() >= MIN_RESIDUES,
                    "{}: {} residues is below the {} floor",
                    p.id,
                    p.sequence.len(),
                    MIN_RESIDUES
                );
            }
        }
    }
}

/// Every entry must say where it came from. This is the rule the whole catalog rests on:
/// an entry we can't trace is an entry we can't show a licence for.
#[test]
fn every_entry_records_its_source() {
    for p in catalog() {
        match p.source {
            "literal" => {
                assert!(
                    !p.reference.is_empty() && p.reference != "-",
                    "{}: a published sequence needs a citation in `reference`",
                    p.id
                );
            }
            "defined" => {
                // An extent of ours has to say both what it was cut from and on what basis.
                assert!(
                    !p.accession.is_empty() && p.accession != "-",
                    "{}: a defined extent needs the accession it was cut from",
                    p.id
                );
                assert!(
                    !p.reference.is_empty() && p.reference != "-",
                    "{}: a defined extent needs the citation that justifies it",
                    p.id
                );
            }
            _ => {
                assert!(
                    !p.accession.is_empty() && p.accession != "-",
                    "{}: a fetched entry needs the accession it came from",
                    p.id
                );
            }
        }
    }
}

/// Every citation has to be a `PMID n` or `DOI x` that could be looked up.
///
/// The generator checks each hand-curated one against the paper its id really names, which
/// needs the network; this is the offline half, so a hand-edited or badly merged catalog
/// can't ship a reference that nothing could resolve. Catalog entries are only auditable
/// if their citations are, and bases with someone else's paper beside them look exactly
/// like bases with the right one.
#[test]
fn every_citation_is_a_resolvable_id() {
    for p in catalog() {
        let pmid = p.reference.strip_prefix("PMID ");
        let doi = p.reference.strip_prefix("DOI ");
        let ok = match (pmid, doi) {
            (Some(id), _) => !id.is_empty() && id.chars().all(|c| c.is_ascii_digit()),
            (_, Some(id)) => id.starts_with("10.") && id.contains('/'),
            _ => false,
        };
        assert!(
            ok,
            "{}: `{}` is not a PMID or DOI that could be looked up",
            p.id, p.reference
        );
    }
}

#[test]
fn ids_and_bases_are_not_repeated() {
    let mut ids: HashMap<&str, ()> = HashMap::new();
    let mut sequences: HashMap<&str, &str> = HashMap::new();
    for p in catalog() {
        assert!(ids.insert(p.id, ()).is_none(), "{}: used twice", p.id);
        if let Some(other) = sequences.insert(p.sequence, p.id) {
            panic!("{} and {} have the same sequence", p.id, other);
        }
    }
}

/// The AMRFinderPlus licence asks for a citation, so it has to survive in the file itself
/// rather than only in the docs.
#[test]
fn the_file_carries_its_attribution() {
    let text = catalog_text();
    assert!(
        text.contains("AMRFinderPlus") && text.contains("31427293"),
        "the catalog header must keep the AMRFinderPlus citation"
    );
    assert!(
        text.contains("docs/feature-catalog.md"),
        "the catalog header must point at the sources doc"
    );
    // CC BY 4.0 asks for UniProt's copyright statement to travel with each copy.
    assert!(
        text.contains("Creative Commons Attribution 4.0 International")
            && text.contains("reproduced with each copy"),
        "the catalog header must keep UniProt's copyright statement"
    );
    assert!(text.contains("FPbase"), "the catalog header must credit FPbase");
}

/// Resistance markers are only useful if `detectFromFeatures` in `src/lib/labinfo.ts`
/// recognises their names — that is what fills Home's contents column and the Info tab's
/// markers. `src/lib/catalog.test.ts` checks the names against that code; here we only
/// make sure the entries it looks for still exist.
#[test]
fn the_expected_markers_are_present() {
    let names: Vec<&str> = catalog().iter().map(|p| p.name).collect();
    for wanted in ["AmpR", "KanR", "CmR", "SpecR", "ori"] {
        assert!(names.contains(&wanted), "the catalog has lost {wanted}");
    }
}
